"""Currency and region reference data (generated by scripts/gen_reference_data.mjs).

currencies.json: active fiat currencies from ISO 4217 List One, with minor units.
regions.json:    countries/regions and the currency CLDR says each currently uses.
                 Used only to *suggest* a display currency; it never restricts a choice.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cache
from pathlib import Path
from typing import Any

_DIR = Path(__file__).parent


@dataclass(frozen=True)
class CurrencyInfo:
    code: str
    name: str
    iso_name: str
    minor_units: int
    used_in: tuple[str, ...]


@cache
def _raw(name: str) -> dict[str, Any]:
    return json.loads((_DIR / name).read_text(encoding="utf-8"))  # type: ignore[no-any-return]


@cache
def currencies() -> dict[str, CurrencyInfo]:
    return {
        c["code"]: CurrencyInfo(c["code"], c["name"], c["iso_name"], int(c["minor_units"]), tuple(c["used_in"]))
        for c in _raw("currencies.json")["currencies"]
    }


@cache
def regions() -> dict[str, dict[str, Any]]:
    return {r["code"]: r for r in _raw("regions.json")["regions"]}


def metadata() -> dict[str, Any]:
    c, r = _raw("currencies.json"), _raw("regions.json")
    return {
        "iso4217_published": c["iso4217_published"],
        "iso4217_source": c["source"],
        "cldr_version": r["cldr_version"],
        "cldr_source": r["source"],
        "currency_count": len(c["currencies"]),
        "region_count": len(r["regions"]),
    }
